window.CHECKLIST = {"meta": {"title": "SPAR Retail Audit — ROC & RTTT", "shortTitle": "Retail Audit", "version": "V3 (27.08.26)", "scoreMax": 3, "passThresholdPct": 80, "scoreNote": "Score each question 0-3 (0 = not met, 3 = fully met), or N/A to exclude it. Each question carries a Weight (%) and a built-in severity (Critical / Major / Partial). Result % = sum(score/3 x weight) / sum(weight). Store passes at 80%.", "severityLevels": ["Critical", "Major", "Partial"], "remediationSeverities": ["Critical", "Major"], "ratingBands": [{"min": 95, "max": 100, "label": "Platinum"}, {"min": 90, "max": 94, "label": "Gold"}, {"min": 80, "max": 89, "label": "Silver"}, {"min": 70, "max": 79, "label": "Bronze"}, {"min": 0, "max": 69, "label": "Improvement Required"}], "source": "RTTT_and_ROC_Checklist.xlsx"}, "storeTypes": [{"label": "TOPS", "audit": "RTTT"}, {"label": "SUPERSPAR", "audit": "ROC"}, {"label": "SPAR", "audit": "ROC"}, {"label": "SAVEMOR", "audit": "ROC"}], "audits": {"ROC": {"id": "ROC", "name": "ROC — Retail Operations Checklist", "storeTypes": ["SUPERSPAR", "SPAR", "SAVEMOR"], "scoreMax": 3, "categories": [{"id": "roc-cat-1", "number": "1", "name": "Exterior & First Impression", "subtitle": "", "questions": [{"id": "roc-q1", "ref": "1", "group": "Parking", "text": "Does the parking area look visibly clean and feel safe for consumers?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Assess overall first impression. Parking should be free from excessive litter, broken glass and illegal dumping. Lighting should appear adequate where applicable. No obvious safety hazards such as potholes, loose paving or damaged kerbs."}, {"id": "roc-q2", "ref": "2", "group": "Signage", "text": "Is the SPAR signage visible and well maintained on the exterior?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Signage should be clearly visible from the road. No faded colours, missing letters, damaged panels or poor illumination. Branding should be current and professionally maintained. Dust build up on the signage. Check dust build up on signages.  Signage must be the new SPAR signage i.e. not the SPAR with the stripes after the tree emblem. Signs are normally made of moulded Perspex and must be in good condition. Externally must have at least 1 moulded Nitec or Flex face sign"}, {"id": "roc-q3", "ref": "3", "group": "Signage", "text": "Is the SPAR flags well visible and maintained", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Flags should be clean, not torn or faded. Flag poles should be upright and secure. Flags should be positioned to maximise visibility. No rust noted on the poles . •\tDeviate for flags if not available and cannot get an answer to why it is not available and the stores will dispute with proof."}, {"id": "roc-q4", "ref": "4", "group": "Trolleys", "text": "Are there sufficient trolleys available at the time of the audit?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "As per spec. SS >150 S 80-100 KS 35-50•\tCustomers should not struggle to obtain a trolley. Consider store size and trading period. Trolley bays should not be empty during normal trading."}, {"id": "roc-q5", "ref": "5", "group": "Trolleys", "text": "Sample of trolleys inspected are clean and suitable for food use.", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Check 10 trolleys  should be clean. There should not be any\nrusted trolley and no broken trolleys in the trolley\nbay. No broken trolleys for example missing wheels\nbroken handles broken baby seats."}, {"id": "roc-q6", "ref": "6", "group": "Promotions", "text": "Are promotional posters visible at the entrance and in good condition, in frames and frames not broken?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Posters should be current promotions only. Frames should not be cracked or broken. Posters should be straight, clean and professionally displayed. There should be no tape holding the posters in the\nframes. The plastic sleeve that goes on the frame\nshould be in good repair."}, {"id": "roc-q7", "ref": "7", "group": "Entrance", "text": "Does the store entrance feel clean and welcoming?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Entrance should be clean, uncluttered and inviting. Doors, windows and entrance mats should be clean. No unpleasant odours."}, {"id": "roc-q8", "ref": "8", "group": "Entrance", "text": "Does the store entrance have the trading hours displayed", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Trading hours should be clearly visible before entering. Information should be accurate and legible. Trading hours board does not need to be the red board . A sticker on the window with the trading hours is acceptable."}]}, {"id": "roc-cat-2", "number": "2", "name": "Interior & First Impression", "subtitle": "", "questions": [{"id": "roc-q9", "ref": "9", "group": "Signage", "text": "Does the store meet the number of signage required store formats, internally", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "SaveMor- 2 signs. SPAR Express- 2 signs, KWICKSPAR- 4 signs, SPAR- 5 signs, SUPERSPAR- 6 signs"}, {"id": "roc-q10", "ref": "10", "group": "Customer Service", "text": "Manager/customer service desk is clean, organised and customer-ready.", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Counter should be free from clutter. Essential customer information should be available. Staff should appear ready to assist customers."}, {"id": "roc-q11", "ref": "11", "group": "Customer Experience", "text": "Hand baskets are available at entrance and visibly accessible to customers.", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Adequate number available. Baskets should be clean and stacked neatly."}]}, {"id": "roc-cat-3", "number": "3", "name": "Store Standards", "subtitle": "", "questions": [{"id": "roc-q12", "ref": "12", "group": "Floors", "text": "Are floors across the store generally clean?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "No litter, spills,  or trip hazards."}, {"id": "roc-q13", "ref": "13", "group": "Compliance", "text": "If floors are being cleaned at the time of the audit, are the floor hazard display markers used?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "wet floor sign- 2"}, {"id": "roc-q14", "ref": "14", "group": "Lighting", "text": "Are all light bulbs / light fittings across the store working?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "No failed fittings affecting customer experience."}, {"id": "roc-q15", "ref": "15", "group": "Temperature", "text": "Is the store at a comfortable temperature?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Store should not feel excessively hot or cold."}, {"id": "roc-q16", "ref": "16", "group": "Flooring", "text": "Are there cracked or missing tiles which will affect the customer experience?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "One is acceptable however when spotting multiple cracked tiles on the shop floor this is a problem"}, {"id": "roc-q17", "ref": "17", "group": "Uniforms", "text": "Apart from the front end, are all staff in uniforms with name badges. Are external merchandisers clearly defined?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Uniforms should be clean. External merchandisers clearly identifiable. •\tName badges should not be hand written give allowance for one or two people , it should not be a standard.•\tStores uniform might have a theme day example on Friday they will soccer shirts , do not deviate for uniform on those days. •\tStores are given 18 months to order new spec uniform do not deviate for old ones."}]}, {"id": "roc-cat-4", "number": "4", "name": "Produce", "subtitle": "", "questions": [{"id": "roc-q18", "ref": "18", "group": "Availability", "text": "Produce range covers the core lines expected for the store's market.", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Supply auditor KVI range by format & trading area. Consider store format and customer demographic. Core fruit and vegetable lines should be available, use list provide of the standard 10 ranges"}, {"id": "roc-q19", "ref": "19", "group": "Cleanliness", "text": "Produce department floor, fixtures and displays are clean.", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "No loose leaves, dirt or standing water. Fixtures should be clean underneath as well."}, {"id": "roc-q20", "ref": "20", "group": "Cleanliness", "text": "Scales in the produce area are clean, sticker-free and functional, where applicable.", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Scale should operate correctly. Display should be readable. No excessive sticker residue."}, {"id": "roc-q21", "ref": "21", "group": "Customer Experience", "text": "Loose produce bags are available and accessible to customers.", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Bags should be stocked and easy to reach.  If the store does not sell loose serve this becomes N/A"}, {"id": "roc-q22", "ref": "22", "group": "Merchandising", "text": "Are the produce boats and displays full and well merchandised?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Displays should appear abundant without excessive overfilling. Good colour blocking and presentation. Minimal empty spaces."}, {"id": "roc-q23", "ref": "23", "group": "Freshness", "text": "No wilted, rotten or damaged produce is visible to customers in produce boats & fridges.", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Inspect several displays. Remove obvious damaged, mouldy or spoiled products. Small isolated defects should be commented on if observed."}, {"id": "roc-q24", "ref": "24", "group": "Pricing", "text": "Every produce item or display has a clearly visible selling price.", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Prices should be easy to identify. No handwritten or missing pricing unless approved."}]}, {"id": "roc-cat-5", "number": "5", "name": "Perishables", "subtitle": "", "questions": [{"id": "roc-q25", "ref": "25", "group": "Availability", "text": "Well merchandised and presentable?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Good presentation. Logical merchandising. Shelves faced."}, {"id": "roc-q26", "ref": "26", "group": "Cleanliness", "text": "Are the shelves clean and free from excessive rust & dirt?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Minor wear acceptable. Excessive rust or dirt fails."}, {"id": "roc-q27", "ref": "27", "group": "Planogram", "text": "Does the store have planograms available and are the teams using these?", "maxScore": 3, "weight": 0, "severity": "Major", "guidance": "Auditor to ask the merchandising team to show planograms Confirm availability with management. Observe whether shelf layout follows planogram principles."}, {"id": "roc-q28", "ref": "28", "group": "Pricing", "text": "Do all products have shelf edge labels or visible pricing?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Sample multiple aisles. Pricing should match products."}]}, {"id": "roc-cat-6", "number": "6", "name": "Grocery", "subtitle": "", "questions": [{"id": "roc-q29", "ref": "29", "group": "Availability", "text": "Are departments well merchandised and presentable?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Good presentation. Logical merchandising. Shelves faced."}, {"id": "roc-q30", "ref": "30", "group": "Cleanliness", "text": "Are the shelves clean and free from excessive rust & dirt?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Minor wear acceptable. Excessive rust or dirt fails."}, {"id": "roc-q31", "ref": "31", "group": "Lighting", "text": "Is aisle lighting working?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "No dark aisles. Replace failed lighting promptly."}, {"id": "roc-q32", "ref": "32", "group": "Planogram", "text": "Does the store have planograms available and are the teams using these?", "maxScore": 3, "weight": 0, "severity": "Major", "guidance": "Auditor to ask the merchandising team to show planograms Confirm availability with management. Observe whether shelf layout follows planogram principles."}, {"id": "roc-q33", "ref": "33", "group": "Pricing", "text": "Do all products have shelf edge labels or visible pricing?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Sample multiple aisles. Pricing should match products."}, {"id": "roc-q34", "ref": "34", "group": "Private Label", "text": "Are there private label products available across most grocery categories?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "5 categories per audit as identified by PL Team•\tLook for SPAR Own Brand across key categories."}]}, {"id": "roc-cat-7", "number": "7", "name": "Bakery", "subtitle": "", "questions": [{"id": "roc-q35", "ref": "35", "group": "Availability", "text": "Bakery  range covers the core lines expected for the store's market.", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Supply auditor KVI range by format & trading area, use list provide of the standard 10 ranges"}, {"id": "roc-q36", "ref": "36", "group": "Cleanliness", "text": "Bakery department floor, fixtures and displays are clean.", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Glass should be clean. Correct temperatures maintained. No burnt food residue. No carted glass"}, {"id": "roc-q37", "ref": "37", "group": "Freshness", "text": "No stale, damaged or poor-quality bakery items are visible on display.", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "No mould, excessive dryness or damaged packaging."}, {"id": "roc-q38", "ref": "38", "group": "Merchandising", "text": "Bakery tables and displays are filled, tidy and free from major gaps.", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Displays should look full and inviting. No excessive empty shelves."}, {"id": "roc-q39", "ref": "39", "group": "Pricing", "text": "Every bakery item or display has a clearly visible selling price.", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "All products should be priced. Pricing should match products displayed. Pricing for pies on the top of the counter is\nacceptable. It does not need to be on each pie."}]}, {"id": "roc-cat-8", "number": "8", "name": "Butchery", "subtitle": "", "questions": [{"id": "roc-q40", "ref": "40", "group": "Freshness", "text": "Does the meat look visually fresh & appealing with no discoloration?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Natural meat colour. No excessive liquid, browning or drying."}, {"id": "roc-q41", "ref": "41", "group": "Cleanliness", "text": "Are the glass and fridges clean, no visible blood and dirty hand prints?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Customer-facing glass should be spotless. Fridges should be clean internally and externally."}, {"id": "roc-q42", "ref": "42", "group": "Merchandising", "text": "Are butchery displays, counters and fridges well and neatly merchandised?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Displays should appear full and organised. Logical product grouping."}, {"id": "roc-q43", "ref": "43", "group": "Pricing", "text": "Is product ticketing displayed clearly with information including product description, allergens, use by date,  price and price per kg?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Product description Price Price/kg Use-by date Allergens where applicable"}, {"id": "roc-q44", "ref": "44", "group": "Availability", "text": "Is a good range of beef, pork (where applicable), lamb and poultry on display to customers at all times of the trading day?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Product mix should suit store market. No major category omissions."}]}, {"id": "roc-cat-9", "number": "9", "name": "Hot Food Counter", "subtitle": "", "questions": [{"id": "roc-q45", "ref": "45", "group": "Availability", "text": "Does the store carry a good Hot Meal range in relation to the market is serves?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Appropriate variety for trading day and customer profile"}, {"id": "roc-q46", "ref": "46", "group": "Cleanliness", "text": "Does the section HMR/Deli area reflect a high standard of cleanliness and hygiene?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Counters, utensils and floors should be clean. No food build-up."}, {"id": "roc-q47", "ref": "47", "group": "Freshness", "text": "Is your impression that the products look fresh and appealing?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "No dried, burnt or over-held food. Food should appear freshly prepared."}, {"id": "roc-q48", "ref": "48", "group": "Cleanliness", "text": "Are the counters & warmers in the HMR/Deli clean and give an impression of food that is safe to eat?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Warmers clean. Food protected."}, {"id": "roc-q49", "ref": "49", "group": "Merchandising", "text": "Are all cabinets and counters well stocked?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Displays should not appear empty during trading."}, {"id": "roc-q50", "ref": "50", "group": "Pricing", "text": "Are prices clearly displayed for all items?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Every product should have visible pricing."}]}, {"id": "roc-cat-10", "number": "10", "name": "Promotions & Pricing", "subtitle": "", "questions": [{"id": "roc-q51", "ref": "51", "group": "Promotions", "text": "Are promotions clearly visible across the store and in aisles, is your perception that the store has products on promotion?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Customers should easily identify promotions throughout the store."}, {"id": "roc-q52", "ref": "52", "group": "Pricing", "text": "Is the promotional price clearly visible to customers on shelf or displays?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Promotional pricing should stand out from standard pricing. POS equipment not necessary required, no sticking on products, laminated allowed"}, {"id": "roc-q53", "ref": "53", "group": "Ticketing", "text": "Is the appropriate themed promotional POS used on shelf ?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Give auditor current promo artwork example. Current campaign POS only. Professional presentation."}, {"id": "roc-q54", "ref": "54", "group": "Displays", "text": "Are promotional displays well executed with enough stock and clear POS/Pricing?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Enough stock and clear POS/Pricing visibility"}, {"id": "roc-q55", "ref": "55", "group": "Gondola Ends", "text": "Are 50% of Gondola Ends used for promotional stock, is there clear POS and do the products & pricing match the leaflet available in store?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "The pricing above the gondola needs to match the price of the product on display. 50% includes that back and front gondola ends combined. Note: Specification for KwikSpar and Expresses to be added on gondola ends. POS equipment not necessary required, no sticking on products, laminated allowed"}]}, {"id": "roc-cat-11", "number": "11", "name": "Back of House", "subtitle": "", "questions": [{"id": "roc-q56", "ref": "56", "group": "Stockroom", "text": "Is the stock room organised?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Clearly organised. Safe stacking. Easy product access."}, {"id": "roc-q57", "ref": "57", "group": "Receiving", "text": "Is the receiving area manned, is a GRV book or process available and is there proof that deliveries are captured via a GRV process?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Observe receiving process. Verify GRV documentation. Receiving stamp available, does not need to be locked away, just available."}, {"id": "roc-q58", "ref": "58", "group": "Waste", "text": "Are there waste controls visible in the receiving area so that spoilt stock and good stock are clearly separated?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Spoilt stock separated from saleable stock. Waste process evident."}, {"id": "roc-q59", "ref": "59", "group": "Cold Rooms", "text": "Are the cold rooms neat, is the temperature acceptable and is there a process to manage waste?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Organised storage. Temperature records available. Waste process evident. Temperature aspect to be removed. Air curtains in the fridge and freezer should be in good repair. If there are no air curtains do not deviate for not having air curtains however if the store has air curtains it should be in good repair."}, {"id": "roc-q60", "ref": "60", "group": "Cleanliness", "text": "Are backup areas clean and free from overloaded clutter?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "No unnecessary clutter. Safe storage practices."}, {"id": "roc-q61", "ref": "61", "group": "Staff Areas", "text": "Are all staff areas clean, neat and hygienic?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Lockers, kitchens and ablutions clean."}, {"id": "roc-q62", "ref": "62", "group": "Staff Areas", "text": "Are facilities made available for staff to store food and heat up food?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Refrigerator and microwave available where applicable. Facilities clean and operational."}, {"id": "roc-q63", "ref": "63", "group": "Staff Areas", "text": "Are there facilities for staff to eat at? Does the area look visually clean & appealing?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Seating available. Hygienic environment. The should adequate seating no crates being used\nto sit on . Adequate ventilation"}]}, {"id": "roc-cat-12", "number": "12", "name": "Checkout & Service", "subtitle": "", "questions": [{"id": "roc-q64", "ref": "64", "group": "Customer Experience", "text": "During the audit, are there excessive queues within the store that aren't managed?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Observe customer wait times. Additional tills should open when required."}, {"id": "roc-q65", "ref": "65", "group": "Customer Experience", "text": "Are the cashiers handling transactions attentively?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Efficient without compromising accuracy, Practical, attentive and not distracted, focusing on the customer"}, {"id": "roc-q66", "ref": "66", "group": "Customer Experience", "text": "Are customers being greeted by cashiers?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Observe customer interactions"}, {"id": "roc-q67", "ref": "67", "group": "Merchandising", "text": "Are there enough impulse merchandising opportunities available to customers at or leading to the point of checkout?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Checkout displays stocked and relevant."}, {"id": "roc-q68", "ref": "68", "group": "Cleanliness", "text": "Does the checkout area look neat, clean and free from clutter?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "No clutter. Clean counters. Bin available"}, {"id": "roc-q69", "ref": "69", "group": "Customer Experience", "text": "Do front end staff understand the store policy for refunds and the refund process?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Auditor to ask cashiers or supervisors to take them through the process"}]}, {"id": "roc-cat-13", "number": "13", "name": "Safety & Compliance", "subtitle": "", "questions": [{"id": "roc-q70", "ref": "70", "group": "Compliance", "text": "Is the Health & Safety Policy displayed?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Displayed and visible"}, {"id": "roc-q71", "ref": "71", "group": "Compliance", "text": "First Aid", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Is a stocked First Aid Kit available. Are qualified first aiders appointed. Is a list of first aiders displayed."}, {"id": "roc-q72", "ref": "72", "group": "Customer Experience", "text": "Does the manager or supervisor understand the procedures for dealing with serious customer complaints: food poisoning/contamination/potential legal issues?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Auditor to ask a manager or supervisor to provide the store process. Process is to contact the ROM and notify of the incident"}, {"id": "roc-q73", "ref": "73", "group": "Electrical COC", "text": "Does the store have a electrical COC in place?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Verify a valid certificate is available and current. Valid for 2 year"}, {"id": "roc-q74", "ref": "74", "group": "Exits", "text": "Are there available emergency exits and are they clear from clutter?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Doors unlocked where required. Exit routes free from obstructions."}, {"id": "roc-q75", "ref": "75", "group": "Fire Safety", "text": "Are fire extinguishers and hoses visible and within allowed service period?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Check service tags. Extinguishers accessible and unobstructed."}, {"id": "roc-q76", "ref": "76", "group": "Gas", "text": "Does the store have a gas COC in place if applicable?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Applicable where gas installations exist. Certificate should be current."}, {"id": "roc-q77", "ref": "77", "group": "Legal Compliance", "text": "Verify visually that 2 wet floor board signs are available.", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Check that the store has a minimum of two wet floor signage available and that they are in a good state of repair"}, {"id": "roc-q78", "ref": "78", "group": "License", "text": "Is the store Trading licence / Business license displayed?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Current licence displayed in accordance with local requirements."}, {"id": "roc-q79", "ref": "79", "group": "License", "text": "Is a current summary of the BCEA displayed and visible to staff.", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Labour law summary should be visible to staff in a common area."}, {"id": "roc-q80", "ref": "80", "group": "License", "text": "Are age restricted sales notices at liquor & tobacco clearly visible?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Notices displayed at liquor and tobacco sales points. Clearly visible to customers."}, {"id": "roc-q81", "ref": "81", "group": "License", "text": "Does the store have a valid liquor license and is this displayed on the shop floor", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "(KZN Does not permit sales of Liquor on the shop floor this is the law) If the store sell Wine or liquor on the shop floor they need to display the liquor license or proof of payment of the liquor license."}, {"id": "roc-q82", "ref": "82", "group": "Security", "text": "Observation, is there a CCTV system operational?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Confirm cameras are operational. Manager should verify monitoring and recording."}]}]}, "RTTT": {"id": "RTTT", "name": "RTTT — TOPS Store Audit", "storeTypes": ["TOPS"], "scoreMax": 3, "categories": [{"id": "rttt-cat-1", "number": "1", "name": "Store Entrance Brand Specification", "subtitle": "", "questions": [{"id": "rttt-q1", "ref": "1", "group": "Entrance & Exits Doors - Trolleys - Baskets - Leaflet Stand - Entrance Mat", "text": "Trading hours board", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Check if the trading hours board is clearly visible at the entrance of the store, The following must be displayed: Emergency numbers, Valid liquor license number, By law liquor not sold to persons under the age of 18 years, Keys to safe not held on site, Right of admission reserved"}]}, {"id": "rttt-cat-2", "number": "2", "name": "Exterior & First Impression", "subtitle": "", "questions": [{"id": "rttt-q2", "ref": "2", "group": "Signage", "text": "Is the SPAR signage visible and well maintained?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Signage should be clearly visible from the road. No faded colours, missing letters, damaged panels or poor illumination. Branding should be current and professionally maintained."}, {"id": "rttt-q3", "ref": "3", "group": "Signage", "text": "Is the SPAR flags well visible and maintained", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Flags should be clean, not torn or faded. Flag poles should be upright and secure. Flags should be positioned to maximise visibility."}, {"id": "rttt-q4", "ref": "4", "group": "Trolleys", "text": "Are there sufficient trolleys available at the time of the audit?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Customers should not struggle to obtain a trolley. Consider store size and trading period. Trolley bays should not be empty during normal trading."}, {"id": "rttt-q5", "ref": "5", "group": "Trolleys", "text": "Sample of trolleys inspected are clean and suitable for food use.", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Check 5 trolleys & 5 baskets"}, {"id": "rttt-q6", "ref": "6", "group": "Promotions", "text": "Are promotional posters visible at the entrance and in good condition, in frames and frames not broken?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Posters should be current promotions. If no Promotions lifestyle posters are acceptable.  Frames should not be cracked or broken. Posters should be straight, clean and professionally displayed."}, {"id": "rttt-q7", "ref": "7", "group": "Entrance", "text": "Does the store entrance feel clean and welcoming?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Entrance should be clean, uncluttered and inviting. Doors, windows and entrance mats should be clean. No unpleasant odours."}, {"id": "rttt-q8", "ref": "8", "group": "Entrance", "text": "Does the store entrance have the trading hours displayed", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Trading hours should be clearly visible before entering. Information should be accurate and legible. This could be a sticker on the glass as long as it is clear and neat."}]}, {"id": "rttt-cat-3", "number": "3", "name": "Interior & First Impression", "subtitle": "", "questions": [{"id": "rttt-q9", "ref": "9", "group": "Customer Service", "text": "Manager/customer service desk is clean, organised and customer-ready.", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Counter should be free from clutter. Essential customer information should be available. Staff should appear ready to assist customers."}, {"id": "rttt-q10", "ref": "10", "group": "Customer Experience", "text": "Hand baskets are available at entrance and visibly accessible to customers.", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Adequate number available. Baskets should be clean and stacked neatly."}]}, {"id": "rttt-cat-4", "number": "4", "name": "Shop Floor", "subtitle": "", "questions": [{"id": "rttt-q11", "ref": "11", "group": "Availability", "text": "Are departments well merchandised and presentable?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Good presentation. Logical merchandising. Shelves faced."}, {"id": "rttt-q12", "ref": "12", "group": "Planogram", "text": "Does the store have planograms available and are the teams using these?", "maxScore": 3, "weight": 0, "severity": "Major", "guidance": "Auditor to ask the merchandising team to show planograms Confirm availability with management. Observe whether shelf layout follows planogram principles."}, {"id": "rttt-q13", "ref": "13", "group": "Cleanliness", "text": "Are the shelves clean and free from excessive rust & dirt?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Minor wear acceptable. Excessive rust or dirt fails."}, {"id": "rttt-q14", "ref": "14", "group": "Merchandising", "text": "Are the majority of the shelves well stocked, products faced up correctly and not too many empty spaces on shelves?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Facing standards maintained. No widespread stock-outs."}, {"id": "rttt-q15", "ref": "15", "group": "Lighting", "text": "Is aisle lighting working?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "No dark aisles. Replace failed lighting promptly."}, {"id": "rttt-q16", "ref": "16", "group": "Pricing", "text": "Do all products have shelf edge labels or visible pricing?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Sample multiple aisles. Pricing should match products."}, {"id": "rttt-q17", "ref": "17", "group": "Cleanliness", "text": "Are the shelves clean and free from excessive rust & dirt?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Minor wear acceptable. Excessive rust or dirt fails."}, {"id": "rttt-q18", "ref": "18", "group": "Availability", "text": "Are departments well merchandised and presentable?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Good presentation. Logical merchandising. Shelves faced."}, {"id": "rttt-q19", "ref": "19", "group": "Cleanliness", "text": "Are the shelves clean and free from excessive rust & dirt?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Minor wear acceptable. Excessive rust or dirt fails."}]}, {"id": "rttt-cat-5", "number": "5", "name": "Promotions & Pricing", "subtitle": "", "questions": [{"id": "rttt-q20", "ref": "20", "group": "Promotions", "text": "Are promotions clearly visible across the store and in aisles, is your perception that the store has products on promotion?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Customers should easily identify promotions throughout the store."}, {"id": "rttt-q21", "ref": "21", "group": "Pricing", "text": "Is the promotional price clearly visible to customers on shelf or displays?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Promotional pricing should stand out from standard pricing."}, {"id": "rttt-q22", "ref": "22", "group": "Promotions", "text": "Is the appropriate themed promotional POS used on shelf ?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Give auditor current promo artwork example. Current campaign POS only. Professional presentation."}, {"id": "rttt-q23", "ref": "23", "group": "Displays", "text": "Are promotional displays well executed with enough stock and clear POS?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Well stocked, Shelves are full and POS has the correct price and description."}]}, {"id": "rttt-cat-6", "number": "6", "name": "Store Standards", "subtitle": "", "questions": [{"id": "rttt-q24", "ref": "24", "group": "Floors", "text": "Are floors across the store generally clean?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "No litter, spills or trip hazards."}, {"id": "rttt-q25", "ref": "25", "group": "Compliance", "text": "If floors are being cleaned at the time of the audit, are the floor hazard display markers used?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Compliance from the Occupational health and safety"}, {"id": "rttt-q26", "ref": "26", "group": "Lighting", "text": "Are all light bulbs / light fittings across the store working?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "No failed fittings affecting customer experience."}, {"id": "rttt-q27", "ref": "27", "group": "Temperature", "text": "Is the store at a comfortable temperature?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Store should not feel excessively hot or cold."}, {"id": "rttt-q28", "ref": "28", "group": "Floors", "text": "Are there cracked or missing tiles which will affect the customer experience?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": ""}, {"id": "rttt-q29", "ref": "29", "group": "Uniforms", "text": "Apart from the front end, are all staff in uniforms with name badges. Are external merchandisers clearly defined?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Uniforms should be clean. External merchandisers clearly identifiable. •\tName badges should not be hand written give allowance for one or two people , it should not be a standard.•\tStores uniform might have a theme day example on Friday they will soccer shirts , do not deviate for uniform on those days. •\tStores are given 18 months to order new spec uniform do not deviate for old ones."}]}, {"id": "rttt-cat-7", "number": "7", "name": "Back of House", "subtitle": "", "questions": [{"id": "rttt-q30", "ref": "30", "group": "Stockroom", "text": "Is the stock room organised?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Clearly organised. Safe stacking. Easy product access."}, {"id": "rttt-q31", "ref": "31", "group": "Receiving", "text": "Is the receiving area manned, is a GRV book or process available and is there proof that deliveries are captured via a GRV process?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Observe receiving process. Verify GRV documentation. Receiving stamp available"}, {"id": "rttt-q32", "ref": "32", "group": "Waste", "text": "Are there waste controls visible in the receiving area so that spoilt stock and good stock are clearly separated?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Spoilt stock separated from saleable stock. Waste process evident."}, {"id": "rttt-q33", "ref": "33", "group": "Cold Rooms", "text": "Are the cold rooms neat, is the temperature acceptable and is there a process to manage waste?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Organised storage. Temperature records available. Waste process evident."}, {"id": "rttt-q34", "ref": "34", "group": "Cleanliness", "text": "Are backup areas clean and free from overloaded clutter?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "No unnecessary clutter. Safe storage practices."}, {"id": "rttt-q35", "ref": "35", "group": "Staff Areas", "text": "Are all staff areas clean, neat and hygienic?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Lockers, kitchens and ablutions clean."}, {"id": "rttt-q36", "ref": "36", "group": "Staff Areas", "text": "Are facilities made available for staff to store food and heat up food?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Refrigerator and microwave available where applicable. Facilities clean and operational."}, {"id": "rttt-q37", "ref": "37", "group": "Staff Areas", "text": "Are there facilities for staff to eat at? Does the area look visually clean & appealing?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Seating available. Hygienic environment."}]}, {"id": "rttt-cat-8", "number": "8", "name": "Checkout & Service", "subtitle": "", "questions": [{"id": "rttt-q38", "ref": "38", "group": "Customer Experience", "text": "During the audit, are there excessive queues within the store that aren't managed?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Observe customer wait times. Additional tills should open when required."}, {"id": "rttt-q39", "ref": "39", "group": "Customer Experience", "text": "Are the cashiers handling transactions with urgency & speed?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Efficient without compromising accuracy"}, {"id": "rttt-q40", "ref": "40", "group": "Customer Experience", "text": "Are customers being greeted by cashiers?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Observe customer interactions"}, {"id": "rttt-q41", "ref": "41", "group": "Brand", "text": "Are the cashiers in uniform, with name badges and appear professional?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Correct uniform. Name badge. Friendly appearance."}, {"id": "rttt-q42", "ref": "42", "group": "Merchandising", "text": "Are there enough impulse merchandising opportunities available to customers at the point of checkout?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Checkout displays stocked and relevant."}, {"id": "rttt-q43", "ref": "43", "group": "Cleanliness", "text": "Does the checkout area look neat, clean and free from clutter?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "No clutter. Clean counters. Bin available"}, {"id": "rttt-q44", "ref": "44", "group": "Customer Experience", "text": "Do front end staff understand the store policy for refunds and the refund process?", "maxScore": 3, "weight": 10, "severity": "Major", "guidance": "Auditor to ask cashiers or supervisors to take them through the process"}]}, {"id": "rttt-cat-9", "number": "9", "name": "Safety & Compliance", "subtitle": "", "questions": [{"id": "rttt-q45", "ref": "45", "group": "Fire Safety", "text": "Are fire extinguishers and hoses visible and within allowed service period?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Check service tags. Extinguishers accessible and unobstructed."}, {"id": "rttt-q46", "ref": "46", "group": "Exits", "text": "Are there available emergency exits and are they clear from clutter?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Doors unlocked where required. Exit routes free from obstructions."}, {"id": "rttt-q47", "ref": "47", "group": "License", "text": "Is the store Trading licence / Business license displayed?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Current licence displayed in accordance with local requirements."}, {"id": "rttt-q48", "ref": "48", "group": "License", "text": "Does the store have a valid liquor license and is this displayed on the shop floor", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Check the expiration date on the liquor license to ensure it is current and has not expired. Confirm that the license details (such as the store name and address) match the store's actual information. Ensure that the license complies with local and state regulations regarding the sale of liquor. Ensure this is displayed visibly on the shop floor."}, {"id": "rttt-q49", "ref": "49", "group": "License", "text": "Is a current summary of the BCEA displayed and visible to staff.", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Labour law summary should be visible to staff in a common area."}, {"id": "rttt-q50", "ref": "50", "group": "Security", "text": "Observation, is there a CCTV system operational?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Confirm cameras are operational. Manager should verify monitoring and recording."}, {"id": "rttt-q51", "ref": "51", "group": "License", "text": "Are age restricted sales notices at liquor & tobacco clearly visible?", "maxScore": 3, "weight": 15, "severity": "Critical", "guidance": "Notices displayed at liquor and tobacco sales points. Clearly visible to customers."}, {"id": "rttt-q52", "ref": "52", "group": "Customer Experience", "text": "Does the manager or supervisor understand the procedures for dealing with serious customer complaints: food poisoning/contamination/potential legal issues?", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Auditor to ask a manager or supervisor to provide the store process"}, {"id": "rttt-q53", "ref": "53", "group": "Legal Compliance", "text": "Verify visually that 2 wet floor board signs are available.", "maxScore": 3, "weight": 5, "severity": "Partial", "guidance": "Check that the store has a minimum of two wet floor signage available and that they are in a good state of repair"}]}]}}};
